def levenshtein(a: str, b: str) -> int:
    prev = list(range(len(b) + 1))          # row 0: D[0][j] = j
    for i, ca in enumerate(a, start=1):
        cur = [i]                           # D[i][0] = i
        for j, cb in enumerate(b, start=1):
            cur.append(min(
                prev[j] + 1,                # delete ca
                cur[j - 1] + 1,             # insert cb
                prev[j - 1] + (ca != cb),   # match or substitute
            ))
        prev = cur
    return prev[-1]

print(levenshtein("kitten", "sitting"))  # 3

ROWS = ["qwertyuiop", "asdfghjkl", "zxcvbnm"]
POS = {ch: (r, c) for r, row in enumerate(ROWS) for c, ch in enumerate(row)}

def adjacent(a, b):
    (r1, c1), (r2, c2) = POS[a], POS[b]
    if r1 == r2:
        return abs(c1 - c2) == 1
    if abs(r1 - r2) != 1:
        return False
    (_, top), (_, low) = sorted([(r1, c1), (r2, c2)])
    return low in (top - 1, top)        # lower row sits half a key right

def sub_cost(a, b):
    return 0.0 if a == b else (0.5 if adjacent(a, b) else 1.0)

def weighted_lev(a, b):
    prev = [float(j) for j in range(len(b) + 1)]
    for i, ca in enumerate(a, start=1):
        cur = [float(i)]
        for j, cb in enumerate(b, start=1):
            cur.append(min(prev[j] + 1,                      # delete ca
                           cur[j - 1] + 1,                   # insert cb
                           prev[j - 1] + sub_cost(ca, cb)))  # match or substitute
        prev = cur
    return prev[-1]

