CODE = {}
for digit, letters in [("1", "bfpv"), ("2", "cgjkqsxz"), ("3", "dt"),
                       ("4", "l"), ("5", "mn"), ("6", "r")]:
    for ch in letters:
        CODE[ch] = digit

def soundex(name):
    name = name.lower()
    out, last = name[0].upper(), CODE.get(name[0], "")
    for ch in name[1:]:
        if ch in "hw":          # h and w do not separate equal digits
            continue
        d = CODE.get(ch, "")    # vowels and y give ""
        if d and d != last:
            out += d
        last = d                # a vowel resets last
    return (out + "000")[:4]

